<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetVersion\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\SnippetVersion\Application\Service\Visibility\SnippetVersionVisibilityService;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\Gateway\SnippetVersionReadGateway;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\Gateway\SnippetVersionFilter;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\Gateway\SnippetVersionCursor;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\Gateway\SnippetVersionAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetVersionListUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SnippetVersionVisibilityService $visibility,
        private readonly SnippetVersionReadGateway $reader
    ) {
    }

    public function allowList(): Allow
    {
        $this->logDebug("Check allow of list usecase for Snippet version");
        $span = $this->startSpan("Check allow of list usecase for Snippet version");
        try {
            $result = $this->dispatcher->dispatch(new SnippetVersionListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function count(SnippetVersionFilter $filter): int
    {
        $this->logDebug("Run list usecase for Snippet version");
        $span = $this->startSpan("Run list usecase for Snippet version");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Snippet version');
            }
            return $this->visibility->countVisibles($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function list(SnippetVersionFilter $filter, ?SnippetVersionCursor $cursor = null): SnippetVersionAttributesSlide
    {
        $this->logDebug("Run list usecase for Snippet version");
        $span = $this->startSpan("Run list usecase for Snippet version");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
            }
            $slide = $this->visibility->listVisibles($filter, $cursor);
            return new SnippetVersionAttributesSlide($slide->nextCursor(), array_map(fn ($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values()));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
